entries[227685] = { ["name"] = "Modified Shadow Scalpel", ["text"] = "Quest Item\nUse: Focus the Modified Shadow Scalpel on Arkonos the Cursed to dispel his barrier of protection.\n\"Cuthbert has imparted Dalton's final blessing upon this instrument. Hopefully it should function to undo the barrier protecting Arkonos.\"" }
