entries[227687] = { ["name"] = "Orthas' Favorite Gold Tooth", ["text"] = "Binds when picked up\nUse: Give Orthas' tooth a... rub. Gross. (2 Min Cooldown)\n\"It smells awful.\"\nSell Price:" }
