entries[227690] = { ["name"] = "Necrotic Runestone", ["text"] = "Quest Item\n\"You feel sick to your stomach when your bare flesh makes contact with this runestone.\"" }
entries[227727] = { ["name"] = "Plans: Sulfuron Hammer", ["text"] = "Unique\nRequires Blacksmithing (300)\n\nUse: Teaches you how to make a Sulfuron Hammer.\nSell Price:\nSulfuron Hammer\nBinds when equipped\nTwo-Hand Mace\n181 - 303 Damage Speed 3.80\n(63.68 damage per second)\n+10 Strength\n+10 Stamina\n+30 Fire Resistance\nDurability 120 / 120\nRequires Level 60\nChance on hit: Hurls a fiery ball that causes 83 to 101 Fire damage and an additional 16 damage over 8 sec.\n\nEquip: Deals 5 Fire damage to anyone who strikes you with a melee attack.\n\nEquip: +124 Attack Power in Cat, Bear, and Dire Bear forms only.\nSell Price:\nRequires Sulfuron Ingot (8), Dark Iron Bar (20), Arcanite Bar (50), Essence of Fire (25), Blood of the Mountain (10), Lava Core (10), Fiery Core (10)" }
entries[227730] = { ["name"] = "Thorium Brotherhood Contract", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n\"Bound in Dark Iron Wiring\"" }
entries[227743] = { ["name"] = "Obsidian Power Core", ["text"] = "Quest Item" }
entries[227745] = { ["name"] = "Family Heirloom", ["text"] = "Binds when picked up\nUnique" }
entries[227746] = { ["name"] = "Rune of the World Tree", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nEngrave your cloak with the Tree of Life rune:\n\nShapeshift into the Tree of Life. While in this form you increase healing received by 10% for all party members within 45 yards, Wild Growth healing is increased by 60%, your heal over time spells cost 20% less, you gain 25% increased Spirit, you gain 200% increased armor, and you cannot cast harmful spells.\n\nThe act of shapeshifting frees the caster of Polymorph and Movement Impairing effects.\n\"Teaches you a new Engraving ability.\"" }
entries[227747] = { ["name"] = "Family Records", ["text"] = "Binds when picked up\nUnique" }
entries[227748] = { ["name"] = "Survivor Journal", ["text"] = "Quest Item\nUnique\n<Right Click to Read>" }
entries[227749] = { ["name"] = "Rune of the Falling Star", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nEngrave your cloak with the Starfall\nrune:\n\nYou summon a flurry of stars from the sky over 10 sec, striking targets within 30 yards of your location, each dealing [source value] to [source value] Arcane damage to its target and [source value] Arcane damage to all other enemies within 5 yards. Maximum 20 stars.\n\nShapeshifting or mounting cancels the effect. Any effect which causes you to lose control of your character will suppress the Starfall effect.\n\nBenefits from and triggers most talents and effects that trigger or benefit from Moonfire.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[227767] = { ["name"] = "Flamestone Cluster", ["text"] = "Quest Item" }
entries[227768] = { ["name"] = "Dreamjuice", ["text"] = "Quest Item\nUnique\nUse: Drink the Dreamjuice to enter a state of waking sleep, allowing you to see hidden enemies. Only usable in Thorium Point. (30 Sec Cooldown)\n3 Charges" }
entries[227796] = { ["name"] = "Mysterious Darnassian Scroll", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nUse: Decipher the scroll with a Comprehension Charm. Who knows what magic it contains?" }
entries[227797] = { ["name"] = "Deciphered Darnassian Scroll", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\n\"Weak magic emanates from the scroll. It may have enough to revitalize the one who wrote it.\"" }
