entries[228250] = { ["name"] = "Plans: Stronger-hold Gauntlets", ["text"] = "Requires Blacksmithing (300)\nRequires Armorsmith\n\nUse: Teaches you how to make Stronghold Gauntlets.\nSell Price:\nStronger-hold Gauntlets\nBinds when equipped\nHands Plate\n441 Armor\n+14 Strength\n+12 Stamina\nDurability 55 / 55\nRequires Level 57\nEquip: Immune to Disarm.\n\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\n\nEquip: Increased Defense +7.\nSell Price:\nRequires Arcanite Bar (15), Enchanted Thorium Bar (20), Essence of Earth (10), Blue Sapphire (4), Large Opal (4)" }
entries[228251] = { ["name"] = "Pattern: Living Green Dragonscale Gauntlets", ["text"] = "Requires Leatherworking (270)\nRequires Dragonscale Leatherworking\n\nUse: Teaches you how to craft Green Dragonscale Leggings.\nSell Price:\nLiving Green Dragonscale Gauntlets\nBinds when equipped\nHands Mail\n208 Armor\n+8 Stamina\n+9 Spirit\n+9 Nature Resistance\nDurability 40 / 40\nRequires Level 51\nEquip: Increases healing done by spells and effects by up to 31.\n\nGreen Dragon Mail (0/3)\nLiving Green Dragonscale Breastplate\nLiving Green Dragonscale Gauntlets\nLiving Green Dragonscale Leggings\nSell Price:\nRequires Rugged Leather (20), Green Dragonscale (25), Rune Thread" }
entries[228276] = { ["name"] = "Pattern: Mastercrafted Shifting Cloak", ["text"] = "Requires Leatherworking (300)\nRequires Elemental Leatherworking\n\nUse: Teaches you how to craft a Shifting Cloak.\nSell Price:\nMastercrafted Shifting Cloak\nBinds when equipped\nBack\n48 Armor\n+17 Agility\n+8 Stamina\nRequires Level 57\nEquip: Increased Defense +8.\nSell Price:\nRequires Rugged Leather (30), Essence of Air (12), Skin of Shadow (4), Guardian Stone (8), Cured Rugged Hide (4), Rune Thread (8)" }
entries[228301] = { ["name"] = "Pattern: Swift Flight Vambraces", ["text"] = "Binds when picked up\nRequires Leatherworking (300)\n\nUse: Teaches you how to craft Swift Flight Bracers.\nSell Price:\nSwift Flight Vambraces\nBinds when equipped\nWrist Mail\n160 Armor\n+7 Agility\nDurability 40 / 40\nRequires Level 57\nEquip: +41 ranged Attack Power.\nSell Price:\nRequires Rugged Leather (12), Larval Acid (8), Ironfeather (60), Cured Rugged Hide (4), Rune Thread (4)" }
entries[228303] = { ["name"] = "Pattern: Incandescent Mooncloth Robe", ["text"] = "Requires Tailoring (300)\n\nUse: Teaches you how to sew a Mooncloth Robe.\nSell Price:\nIncandescent Mooncloth Robe\nBinds when equipped\nChest Cloth\n89 Armor\n+12 Intellect\n+10 Spirit\nDurability 80 / 80\nRequires Level 58\nEquip: Increases healing done by spells and effects by up to 62.\nSell Price:\nRequires Bolt of Runecloth (6), Mooncloth (4), Golden Pearl (2), Rune Thread (2)" }
entries[228309] = { ["name"] = "Pattern: Living Green Dragonscale Breastplate", ["text"] = "Requires Leatherworking (260)\nRequires Dragonscale Leatherworking\n\nUse: Teaches you how to craft a Green Dragonscale Breastplate.\nSell Price:\nLiving Green Dragonscale Breastplate\nBinds when equipped\nChest Mail\n311 Armor\n+10 Stamina\n+14 Spirit\n+11 Nature Resistance\nDurability 120 / 120\nRequires Level 47\nEquip: Increases healing done by spells and effects by up to 31.\n\nGreen Dragon Mail (0/3)\nLiving Green Dragonscale Breastplate\nLiving Green Dragonscale Gauntlets\nLiving Green Dragonscale Leggings\nSell Price:\nRequires Rugged Leather (20), Green Dragonscale (25), Rune Thread (2)" }
entries[228310] = { ["name"] = "Plans: Hardened Frostguard", ["text"] = "Requires Blacksmithing (300)\nRequires Master Swordsmith\n\nUse: Teaches you how to make a Frostguard.\nSell Price:\nHardened Frostguard\nBinds when equipped\nMain Hand Sword\n54 - 101 Damage Speed 1.50\n(51.67 damage per second)\n+4 Stamina\nDurability 90 / 90\nRequires Level 60\nChance on hit: Target's movement slowed by 30% and increasing the time between attacks by 25% for 5 sec.\n\nChance on hit: Inflicts Frost damage to nearby enemies, immobilizing them for up to 8 sec.\nSell Price:\nRequires Frostguard , Elemental Sharpening Stone (10)" }
entries[228311] = { ["name"] = "Plans: Finely-Enchanted Battlehammer", ["text"] = "Requires Blacksmithing (280)\nRequires Master Hammersmith\n\nUse: Teaches you how to make an Enchanted Battlehammer.\nSell Price:\nFinely-Enchanted Battlehammer\nBinds when equipped\nTwo-Hand Mace\n106 - 160 Damage Speed 2.60\n(51.15 damage per second)\nDurability 100 / 100\nRequires Level 55\nEquip: Increased Defense +13.\n\nEquip: Improves your chance to hit with all spells and attacks by 2%.\n\nEquip: +109 Attack Power in Cat, Bear, and Dire Bear forms only.\nSell Price:\nRequires Thorium Bar (20), Enchanted Thorium Bar (6), Huge Emerald (2), Powerful Mojo (4), Rugged Leather (4)" }
entries[228312] = { ["name"] = "Plans: Invincible Mail", ["text"] = "Requires Blacksmithing (300)\nRequires Armorsmith\n\nUse: Teaches you how to make Invincible Mail.\nSell Price:\nInvincible Mail\nBinds when equipped\nChest Mail\n416 Armor\n+20 Stamina\nDurability 140 / 140\nRequires Level 60\nEquip: When struck in combat has a 5% chance to make you invulnerable to melee damage for 3 sec. This effect can only occur once every 30 sec. (Proc chance: 5%, 30s cooldown)\n\nEquip: Increased Defense +13.\nSell Price:\nRequires Arcanite Bar (30), Enchanted Thorium Bar (30), Huge Emerald (6), Azerothian Diamond (6)" }
entries[228313] = { ["name"] = "Plans: Tempest Gauntlets", ["text"] = "Requires Blacksmithing (295)\nRequires Armorsmith\n\nUse: Teaches you how to make Tempest Gauntlets.\nSell Price:\nTempest Gauntlets\nBinds when equipped\nHands Mail\n218 Armor\n+7 Intellect\n+10 Fire Resistance\nDurability 40 / 40\nRequires Level 54\nEquip: Adds 3 Lightning damage to your melee attacks.\n\nEquip: Increases damage and healing done by magical spells and effects by up to 18.\nSell Price:\nRequires Thorium Bar (20), Enchanted Thorium Bar (4), Essence of Water (4), Blue Sapphire (4)" }
entries[228314] = { ["name"] = "Plans: Warcrest of the Great Chief", ["text"] = "Requires Blacksmithing (300)\nRequires Armorsmith\n\nUse: Teaches you how to make a Warcrest of the Great Chief.\nSell Price:\nWarcrest of the Great Chief\nBinds when equipped\nHead Mail\n292 Armor\n+12 Stamina\n+18 Spirit\nDurability 70 / 70\nRequires Level 56\nEquip: Increases healing done by spells and effects by up to 46.\nSell Price:\nRequires Thorium Bar (40), Enchanted Thorium Bar (4), Jet Black Feather (60), Large Opal (6), Huge Emerald (2)" }
entries[228315] = { ["name"] = "Plans: Sageblade of the Archmagus", ["text"] = "Requires Blacksmithing (300)\nRequires Master Swordsmith\n\nUse: Teaches you how to make a Sageblade of the Archmagus.\nSell Price:\nSageblade of the Archmagus\nBinds when equipped\nMain Hand Sword\n47 - 103 Damage Speed 1.80\n(41.67 damage per second)\n+14 Stamina\n+10 Intellect\nDurability 105 / 105\nRequires Level 60\nEquip: Increases damage and healing done by magical spells and effects by up to 41.\n\nEquip: Decreases the magical resistances of your spell targets by 10.\nSell Price:\nRequires Arcanite Bar (12), Nexus Crystal (2), Flask of Supreme Power (2), Enchanted Leather (4)" }
