entries[231797] = { ["name"] = "Soul of the Void", ["text"] = "Binds when picked up\nUse: Combine the soul shard with the Depleted Scythe of Chaos." }
entries[231798] = { ["name"] = "Soul of Enthralling", ["text"] = "Binds when picked up\nUse: Combine the soul shard with the Depleted Scythe of Chaos." }
