entries[231828] = { ["name"] = "Rune of Meditation Specialization", ["text"] = "Binds to account\nUnique\nClasses: Paladin , Hunter , Priest , Shaman , Mage , Warlock , Druid\nEngrave your ring with the Meditation Specialization rune:\n\nRestores 5 mana per 5 sec. This effect is not cumulative with other ring runes.\n\"Teaches you a new Engraving ability.\"" }
entries[231829] = { ["name"] = "Rune of Healing Specialization", ["text"] = "Binds to account\nUnique\nClasses: Paladin , Priest , Shaman , Mage , Druid\nEngrave your ring with the Healing Specialization rune:\n\nIncreases healing done by spells and effects by up to 26. This effect is not cumulative with other ring runes.\n\"Teaches you a new Engraving ability.\"" }
entries[231836] = { ["name"] = "Glowing Scroll of Spatial Mending", ["text"] = "Quest Item\nUse: Close a targeted Fel portal. May draw unwanted attention from the other side." }
entries[231837] = { ["name"] = "Shadow Carving", ["text"] = "Quest Item\nUnique\n\"It appears to attract shadow energy.\"" }
entries[231841] = { ["name"] = "Blood of the Lightbringer", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nRequires Level 60\n\"This small reliquary is filled with a small sample of blood. There is a partially torn parchment label on the underside that bears a single word: \"Uther\".\"" }
entries[231843] = { ["name"] = "First Sigil Fragment", ["text"] = "Binds when picked up\nUnique\nUse: Combine with two other pieces to form the Sigil of the Keeper." }
entries[231844] = { ["name"] = "Second Sigil Fragment", ["text"] = "Binds when picked up\nUnique\nUse: Combine with two other pieces to form the Sigil of the Keeper." }
entries[231845] = { ["name"] = "Third Sigil Fragment", ["text"] = "Binds when picked up\nUnique\nUse: Combine with two other pieces to form the Sigil of the Keeper." }
entries[231877] = { ["name"] = "Tyler's Balanced Bobble", ["text"] = "Binds when picked up\nTrinket\nSell Price:" }
entries[231901] = { ["name"] = "Truthbearer", ["text"] = "Quest Item\nUnique\nClasses: Paladin\nRequires Level 60" }
entries[231903] = { ["name"] = "Scrap of Torn Cloth", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nRequires Level 60\n\"A small scrap of cloth from Uther the Lightbringer's tunic containing a few flecks of blood.\"" }
entries[231904] = { ["name"] = "Tarnished Horn", ["text"] = "Quest Item\nUnique\nRequires Level 50\n\nUse: Sound the horn to call Aeonas back to you should you get separated. This will also cancel any magical disguises you have active. (15 Sec Cooldown)" }
entries[231909] = { ["name"] = "Crystallized Starlight", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nUse: Attune with the heavens, allowing you to replace your Moonkin form with a more celestial visage." }
entries[232312] = { ["name"] = "Blood of the Lightbringer", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nRequires Level 60\n\nUse: Apply the Blood of the Lightbringer to consecrate your weapon." }
entries[232324] = { ["name"] = "Bird Whistle", ["text"] = "Binds when picked up\nUse: Calls forth Pepe to ride on your head as you adventure together.\nSell Price:" }
entries[232344] = { ["name"] = "Vick's VIP Pass", ["text"] = "Unique\nUse: Attune yourself to Blackwing Lair! (30 Sec Cooldown)\n\"For close personal friends of Lord Victor Nefarius only!\"\nSell Price:" }
entries[232358] = { ["name"] = "Empty Reliquary", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nRequires Level 60" }
entries[232414] = { ["name"] = "Dragontooth Blade", ["text"] = "Quest Item\nUnique\nClasses: Warrior\nRequires Level 60\n\nUse: Carve a scale from Nefarian's hide. Only usable when Nefarian has been significantly weakened in battle. (10 Sec Cooldown)" }
entries[232433] = { ["name"] = "Dense Runecloth Bandage", ["text"] = "Requires Level 50\nRequires First Aid (300)\n\nUse: Heals 3400 damage over 8 sec.\nSell Price:" }
entries[232434] = { ["name"] = "Manual: Dense Runecloth Bandage", ["text"] = "Requires First Aid (300)\n\nUse: Teaches you how to make a Dense Runecloth Bandage.\nSell Price:\nDense Runecloth Bandage\nRequires Level 50\nRequires First Aid (300)\n\nUse: Heals 3400 damage over 8 sec.\nSell Price:\nRequires Heavy Runecloth Bandage (2)" }
entries[232436] = { ["name"] = "Darkclaw Bisque", ["text"] = "Requires Level 45\n\nUse: Restores 2148 health over 30 sec. Must remain seated while eating. If you eat for 10 seconds will also increase your Spell Damage by 12 for 10 min.\nSell Price:" }
entries[232437] = { ["name"] = "Recipe: Darkclaw Bisque", ["text"] = "Requires Cooking (300)\n\nUse: Teaches you how to cook Darkclaw Bisque.\nSell Price:\nDarkclaw Bisque\nRequires Level 45\n\nUse: Restores 2148 health over 30 sec. Must remain seated while eating. If you eat for 10 seconds will also increase your Spell Damage by 12 for 10 min.\nSell Price:\nRequires Darkclaw Lobster , Drinkable Stratholme Holy Water" }
entries[232438] = { ["name"] = "Smoked Redgill", ["text"] = "Requires Level 35\n\nUse: Restores 1392 health over 30 sec. Must remain seated while eating. If you eat for 10 seconds will also increase your Healing done by 22 for 10 min.\nSell Price:" }
entries[232443] = { ["name"] = "Recipe: Smoked Redgill", ["text"] = "Requires Cooking (300)\n\nUse: Teaches you how to cook Smoked Redgill.\nSell Price:\nSmoked Redgill\nRequires Level 35\n\nUse: Restores 1392 health over 30 sec. Must remain seated while eating. If you eat for 10 seconds will also increase your Healing done by 22 for 10 min.\nSell Price:\nRequires Raw Redgill" }
entries[232454] = { ["name"] = "Emblem of the Wild Gods", ["text"] = "Binds to account\n\"Proof of assisting the Shadowtooth Emissary. Redeemable at the Rune Broker in capital cities.\"" }
entries[232455] = { ["name"] = "Emblem of Dishonor", ["text"] = "Binds to account\n\"Proof of confronting Illari Duskfeather. Redeemable at the Rune Broker in capital cities.\"" }
entries[232456] = { ["name"] = "Emblem of the Violet Eye", ["text"] = "Binds to account\n\"Proof of victory over the Dark Riders. Redeemable at the Rune Broker in capital cities.\"" }
entries[232457] = { ["name"] = "Emblem of the Worldcore", ["text"] = "Binds to account\n\"Proof of atunning to the Leyline Confluxes. Redeemable at the Rune Broker in capital cities.\"" }
entries[232458] = { ["name"] = "Rune of Improved Sanctuary", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nEngrave your helm with the Improved Sanctuary rune:\n\nIncreases the damage prevented by your Blessing of Sanctuary by 100%, and increases damage done by your Blessing of Sanctuary by 20% of your shield block value.\n\"Teaches you a new Engraving ability.\"" }
entries[232459] = { ["name"] = "Rune of Backdraft", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your helm with the Backdraft rune:\n\nYour Conflagrate ability also grants 30% spellcasting haste for 15 sec and no longer consumes Immolate.\n\"Teaches you a new Engraving ability.\"" }
entries[232460] = { ["name"] = "Rune of Displacement", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your bracers with the Displacement rune:\n\nTeleports back to where you last cast Blink from and resets the cooldown on Blink. Only usable within 10 sec of casting Blink.\n\"Teaches you a new Engraving ability.\"" }
entries[232461] = { ["name"] = "Rune of Despair", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your bracers with the Despair rune:\n\nPeriodic damage from your spells can now be critical strikes and all your damaging spell critical strikes deal 200% damage.\n\"Teaches you a new Engraving ability.\"" }
entries[232462] = { ["name"] = "Rune of Purifying Power", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nEngrave your bracers with the Purifying Power rune:\n\nReduces the cooldown on Exorcism and Holy Wrath by 50%, and Holy Wrath can now be cast at any target and will Stun Undead and Demon targets for 2 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[232549] = { ["name"] = "Logistics Task Briefing VI", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60" }
entries[232610] = { ["name"] = "Formula: Magnificent Trollshine", ["text"] = "Binds when picked up\nRequires Enchanting (300)\nRequires Zandalar Tribe\n- Honored\n\nUse: Teaches you how to create Magnificent Trollshine.\nSell Price:\nMagnificent Trollshine\nRequires Level 45\n\nUse: While applied to target shield it increases spell damage and healing by up to 36 and increases Spell Critical chance by 1%. Lasts for 30 minutes.\n5 Charges\nSell Price:\nRequires Flask of Mojo (3), Flask of Big Mojo (3), Large Brilliant Shard (2), Imbued Vial" }
entries[232611] = { ["name"] = "Magnificent Trollshine", ["text"] = "Requires Level 45\n\nUse: While applied to target shield it increases spell damage and healing by up to 36 and increases Spell Critical chance by 1%. Lasts for 30 minutes.\n5 Charges\nSell Price:" }
entries[232652] = { ["name"] = "Zila Amanemodas", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nUse: Attune with the darkness within, allowing you better control over your inner demon." }
entries[233197] = { ["name"] = "Argent Training Manual", ["text"] = "Binds when picked up\nRequires Level 50\n\nUse: Use the manual to call your Argent Squire for a training lesson in combat with the Silithid. Silithids killed in the squire's presence will increase your reputation with the Argent Dawn. (5 Min Cooldown)\n3 Charges" }
entries[233198] = { ["name"] = "Horn of the Dawn", ["text"] = "Binds when picked up\nRequires Level 50\n\nUse: Rally your nearby party or raid members, granting them 10% increased spell critical strike chance, 5% increased melee and ranged critical strike chance, and 140 increased attack power. Lasts 2 hrs. Exclusive with similar world effects and unaffected by Chronoboons. (30 Sec Cooldown)" }
entries[233200] = { ["name"] = "Songflower Seed", ["text"] = "Binds when picked up\nRequires Level 50\n\nUse: Summon a songflower that grants all your party or raid members 5% increased chance for a melee, ranged, or spell critical and 15 increased attributes for 1 hour. Exclusive with similar world effects. Unaffected by Chronoboons. (30 Sec Cooldown)" }
entries[233209] = { ["name"] = "Firewater Cauldron", ["text"] = "Binds when picked up\nRequires Level 50\n\nUse: Summon a cauldron of Firewater for 10 min, useable by all members of your party or raid to increase melee attack power by 35 and size for 1 hour. (30 Sec Cooldown)" }
entries[233217] = { ["name"] = "Tunneler's Incense", ["text"] = "Binds when picked up\nRequires Level 50\n\nUse: Inhaling this incense causes you to fade into the shadows, allowing you to sneak around while inside Hive'Ashi, Hive'Regal, or Hive'Zora, but reduces your speed by 50%. Lasts 1 min. (1 Min Cooldown)\n10 Charges\nSell Price:" }
entries[233250] = { ["name"] = "Ancient Branch", ["text"] = "Binds when picked up\nRequires Level 50\n\nUse: Use the branch to call an Ancient of War to assist you in fighting Silithids. (15 Min Cooldown)\n3 Charges" }
entries[234012] = { ["name"] = "Hive Thistle", ["text"] = "Sell Price:" }
entries[234016] = { ["name"] = "Signet Ring of the Bronze Dragonflight", ["text"] = "Binds when picked up\nUnique-Equipped: Signet Ring of the Bronze Dragonflight (1)\nFinger\n+6 Stamina\n+7 Intellect\nRequires Level 60\nRequires Brood of Nozdormu\n- Neutral\nEquip: Improves your chance to hit with all spells and attacks by 1%.\n\nEquip: Increases damage and healing done by magical spells and effects by up to 21.\n\nEquip: Increases the casting speed of your spells by 2% per piece of Timeworn armor equipped.\n\"The Path of the Invoker\"" }
entries[234017] = { ["name"] = "Signet Ring of the Bronze Dragonflight", ["text"] = "Binds when picked up\nUnique-Equipped: Signet Ring of the Bronze Dragonflight (1)\nFinger\n+18 Strength\n+8 Stamina\nRequires Level 60\nRequires Brood of Nozdormu\n- Neutral\nEquip: Improves your chance to hit with all spells and attacks by 1%.\n\nEquip: Gives you 1% chance per piece of Timeworn armor equipped to get an extra attack on melee or ranged hit. (Proc chance: 8%, 200ms cooldown)\n\"The Path of the Dominator\"" }
entries[234018] = { ["name"] = "Signet Ring of the Bronze Dragonflight", ["text"] = "Binds when picked up\nUnique-Equipped: Signet Ring of the Bronze Dragonflight (1)\nFinger\n+10 Strength\n+18 Stamina\nRequires Level 60\nRequires Brood of Nozdormu\n- Neutral\nEquip: Increased Defense +5.\n\nEquip: Reduces the chance for your attacks to be dodged or parried by 1% per piece of Timeworn armor equipped.\n\"The Path of the Protector\"" }
entries[234019] = { ["name"] = "Signet Ring of the Bronze Dragonflight", ["text"] = "Binds when picked up\nUnique-Equipped: Signet Ring of the Bronze Dragonflight (1)\nFinger\n+6 Stamina\n+7 Intellect\nRequires Level 60\nRequires Brood of Nozdormu\n- Neutral\nEquip: Increases healing done by up to 40 and damage done by up to 14 for all magical spells and effects.\n\nEquip: Restores 3 mana per 5 sec.\n\nEquip: Increases the effectiveness of your healing and shielding spells by 2% per piece of Timeworn armor equipped.\n\"The Path of the Preserver\"" }
