entries[234202] = { ["name"] = "Signet Ring of the Bronze Dragonflight", ["text"] = "Binds when picked up\nUnique-Equipped: Signet Ring of the Bronze Dragonflight (1)\nFinger\n+24 Agility\n+13 Stamina\nRequires Level 60\nRequires Brood of Nozdormu\n- Exalted\nEquip: Improves your chance to hit with all spells and attacks by 1%.\n\nEquip: Gives you 1% chance per piece of Timeworn armor equipped to get an extra attack on melee or ranged hit. (Proc chance: 8%, 200ms cooldown)\n\"The Path of the Conqueror\"" }
entries[234271] = { ["name"] = "Formula: Scroll: Wrath of the Swarm", ["text"] = "Binds when picked up\nRequires Enchanting (300)\nRequires Cenarion Circle\n- Friendly\n\nUse: Teaches you how to conjure a Scroll: Wrath of the Swarm.\nSell Price:\nScroll: Wrath of the Swarm\nBinds when picked up\nRequires Level 60\nRequires Enchanting (300)\n\nUse: Read from the scroll, evoking the Wrath of the Swarm, empowering your raid to deal up to 40 increased damage and healing with spells, and increasing attack power by 40 for 1 hour. (1 Min Cooldown)\nRequires Greater Eternal Essence , Runecloth" }
entries[234272] = { ["name"] = "Formula: Enchanted Repellent", ["text"] = "Binds when picked up\nRequires Enchanting (300)\nRequires Cenarion Circle\n- Friendly\n\nUse: Teaches you how to create Enchanted Repellent.\nSell Price:\nEnchanted Repellent\nRequires Level 60\n\nUse: While applied to target weapon or shield it increases spell damage by up to 45 and increases Spell Critical chance by 1% . Lasts for 30 minutes.\n5 Charges\nSell Price:\nRequires Qiraji Stalker Venom (3), Hive Thistle (3), Illusion Dust (2)" }
entries[234436] = { ["name"] = "Signet Ring of the Bronze Dragonflight", ["text"] = "Binds when picked up\nUnique-Equipped: Signet Ring of the Bronze Dragonflight (1)\nFinger\n+8 Stamina\n+9 Intellect\nClasses: Priest , Warlock , Druid\nRequires Level 60\nRequires Brood of Nozdormu\n- Exalted\nEquip: Increases damage and healing done by magical spells and effects by up to 30.\n\nEquip: Increases the damage dealt by all of your damage over time spells by 3% per piece of Timeworn armor equipped.\n\"The Path of the Subjugator\"" }
