entries[235597] = { ["name"] = "Spell Notes: Deep Freeze", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your helm with the Deep Freeze rune:\n\nStuns the target for 5 sec. Only usable on Frozen targets. Deals [source value] to [source value] damage to targets permanently immune to Stun. This damage benefits from, but does not consume, stacks of Glaciate.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[235598] = { ["name"] = "Spell Notes: Icy Veins", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your pants with the Icy Veins rune:\n\nHastens your spellcasting, increasing spell casting speed by 20% and reduces the pushback suffered from damaging attacks while casting by 100%. Lasts 20 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[235599] = { ["name"] = "Spell Notes: Temporal Anomaly", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your helm with the Temporal Anomaly rune:\n\nLaunches an orb of temporal energy which slowly moves forward and every 2 sec grants all nearby party members a shield absorbing [source value] damage for 15 sec. This shield accumulates additional value if party members remain near the orb.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[235600] = { ["name"] = "Rune of Divine Storm", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nEngrave your chest with the Divine Storm rune:\n\nAn instant weapon attack that causes 110% of weapon damage to up to 4 enemies within 8 yards. The Divine Storm heals up to 3 party or raid members totaling 25% of the damage caused.\n\"Teaches you a new Engraving ability.\"" }
entries[235601] = { ["name"] = "Rune of Fanaticism", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nEngrave your helm with the Fanaticism rune:\n\nIncreases your critical strike chance with Holy spells by 18%. In addition, your critical healing spells heal the target for 60% of the healed amount over 12 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[235602] = { ["name"] = "Rune of Hammer of the Righteous", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nEngrave your bracers with the Hammer of the Righteous rune:\n\nHammer the current target and up to 3 additional nearby targets, causing 4 times your main hand damage per second as Holy damage.\n\"Teaches you a new Engraving ability.\"" }
entries[235603] = { ["name"] = "Rune of Righteous Vengeance", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nEngrave your cloak with the Righteous Vengeance rune:\n\nWhen your Judgement, Crusader Strike, or Divine Storm deals a critical strike, your target will take 30% additional damage over until cancelled.\n\"Teaches you a new Engraving ability.\"" }
entries[235604] = { ["name"] = "Rune of Shield of Righteousness", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nEngrave your cloak with the Shield of Righteousness rune:\n\nSlam the target with your shield, causing Holy damage based on your block value plus an additional [source value].\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[235605] = { ["name"] = "Rune of Shock and Awe", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nEngrave your cloak with the Shock and Awe rune:\n\nWhile Righteous Fury is not active, dealing Holy Shock damage grants 200% of your Intellect as Spell Damage and reduces the threat you generate by 30% for 1 min.\n\nIf Infusion of Light is engraved, gain Sunlight for 10 sec.\n\nSunlight causes Divine Storm, Crusader Strike, and melee attacks against non-player controlled targets to deal bonus Holy damage equal to 60% of your holy spell power.\n\"Teaches you a new Engraving ability.\"" }
