entries[239512] = { ["name"] = "Lightbreaker Wrists", ["text"] = "Sanctified\nBinds when picked up\nWrist Plate\n477 Armor\n+29 Strength\n+10 Agility\n+13 Stamina\nDurability 55 / 55\nClasses: Warrior\nRequires Level 60\nEquip: Improves your chance to hit with all spells and attacks by 1%.\n\nEquip: Increases your attack speed by 1%.\n\nLightbreaker's Warplate (0/8)\nLightbreaker Greathelm\nLightbreaker Shoulders\nLightbreaker Cuirass\nLightbreaker Belt\nLightbreaker Tassets\nLightbreaker Greaves\nLightbreaker Wrists\nLightbreaker Grips\n(2) Set : Your Heroic Strike, Cleave, and Quick Strike damage is increased by 20% while in Battle Stance or Berserker Stance. Your Cleave strikes 1 additional target and can trigger Blood Surge.\n(4) Set : Each time you hit a target with Whirlwind, Heroic Strike, Quick Strike, or Cleave, the damage of your next Slam is increased by 20%, stacking up to 5 times.\n(6) Set : Each time Deep Wounds deals damage, it reduces the remaining cooldown on your Whirlwind by 3 sec. Whirlwind deals 100% increased damage to targets afflicted with your Deep Wounds.\nSell Price:" }
entries[239513] = { ["name"] = "Lightbreaker Belt", ["text"] = "Sanctified\nBinds when picked up\nWaist Plate\n613 Armor\n+36 Strength\n+10 Agility\n+18 Stamina\nDurability 55 / 55\nClasses: Warrior\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\n\nEquip: Increases your attack speed by 2%.\n\nLightbreaker's Warplate (0/8)\nLightbreaker Greathelm\nLightbreaker Shoulders\nLightbreaker Cuirass\nLightbreaker Belt\nLightbreaker Tassets\nLightbreaker Greaves\nLightbreaker Wrists\nLightbreaker Grips\n(2) Set : Your Heroic Strike, Cleave, and Quick Strike damage is increased by 20% while in Battle Stance or Berserker Stance. Your Cleave strikes 1 additional target and can trigger Blood Surge.\n(4) Set : Each time you hit a target with Whirlwind, Heroic Strike, Quick Strike, or Cleave, the damage of your next Slam is increased by 20%, stacking up to 5 times.\n(6) Set : Each time Deep Wounds deals damage, it reduces the remaining cooldown on your Whirlwind by 3 sec. Whirlwind deals 100% increased damage to targets afflicted with your Deep Wounds.\nSell Price:" }
entries[239514] = { ["name"] = "Lightbreaker Grips", ["text"] = "Sanctified\nBinds when picked up\nHands Plate\n681 Armor\n+35 Strength\n+8 Agility\n+13 Stamina\nDurability 55 / 55\nClasses: Warrior\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\n\nEquip: Reduces the chance for your attacks to be dodged or parried by 1%.\n\nEquip: Increases your attack speed by 2%.\n\nLightbreaker's Warplate (0/8)\nLightbreaker Greathelm\nLightbreaker Shoulders\nLightbreaker Cuirass\nLightbreaker Belt\nLightbreaker Tassets\nLightbreaker Greaves\nLightbreaker Wrists\nLightbreaker Grips\n(2) Set : Your Heroic Strike, Cleave, and Quick Strike damage is increased by 20% while in Battle Stance or Berserker Stance. Your Cleave strikes 1 additional target and can trigger Blood Surge.\n(4) Set : Each time you hit a target with Whirlwind, Heroic Strike, Quick Strike, or Cleave, the damage of your next Slam is increased by 20%, stacking up to 5 times.\n(6) Set : Each time Deep Wounds deals damage, it reduces the remaining cooldown on your Whirlwind by 3 sec. Whirlwind deals 100% increased damage to targets afflicted with your Deep Wounds.\nSell Price:" }
entries[239515] = { ["name"] = "Lightbreaker Greaves", ["text"] = "Sanctified\nBinds when picked up\nFeet Plate\n749 Armor\n+35 Strength\n+10 Agility\n+11 Stamina\nDurability 75 / 75\nClasses: Warrior\nRequires Level 60\nEquip: Improves your chance to hit with all spells and attacks by 1%.\n\nEquip: Increases your attack speed by 2%.\n\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\n\nLightbreaker's Warplate (0/8)\nLightbreaker Greathelm\nLightbreaker Shoulders\nLightbreaker Cuirass\nLightbreaker Belt\nLightbreaker Tassets\nLightbreaker Greaves\nLightbreaker Wrists\nLightbreaker Grips\n(2) Set : Your Heroic Strike, Cleave, and Quick Strike damage is increased by 20% while in Battle Stance or Berserker Stance. Your Cleave strikes 1 additional target and can trigger Blood Surge.\n(4) Set : Each time you hit a target with Whirlwind, Heroic Strike, Quick Strike, or Cleave, the damage of your next Slam is increased by 20%, stacking up to 5 times.\n(6) Set : Each time Deep Wounds deals damage, it reduces the remaining cooldown on your Whirlwind by 3 sec. Whirlwind deals 100% increased damage to targets afflicted with your Deep Wounds.\nSell Price:" }
